S[2].range());\nexport const currentIndexAtom = atom<any>([]);\nexport const selectedIndexesAtom = atom<any>([]);\nexport const searchValueAtom = atom('');\nexport const searchFocusAtom = atom(false);\nexport const activeShortcutAtom = atom<ShortcutItem | undefined>(DISCOVER_SHORTCUTS[2]);\nexport const dorisInfoAtom = atom<any>({});\nexport const disabledOptionsAtom = atom<string[]>([]);\n\nexport const selectedFieldsAtom = atom<any[]>([]);\nexport const tableFieldsAtom = atom<any[]>([]);\n\nexport const timeFieldsAtom = atom<any[]>([]);\nexport const tableDataAtom = atom<any[]>([]);\nexport const topDataAtom = atom<any[]>([]);\nexport const surroundingTableDataAtom = atom<any[]>([]);\nexport const tableDataChartsAtom = atom<any[]>([]);\nexport const intervalAtom = atom<IntervalEnum>(IntervalEnum.Auto);\nexport const tableTotalCountAtom = atom<number>(0);\nexport const tableEChartsDataAtom = atom<any[]>([]);\nexport const tableTracesDataAtom = atom<any>();\n\n// Filter Content Atom\nexport const searchableAtom = atom<SearchableEnum>(SearchableEnum.ANY);\nexport const aggregatableAtom = atom<AggregatableEnum>(AggregatableEnum.ANY);\nexport const fieldTypeAtom = atom<FieldTypeEnum>(FieldTypeEnum.ANY);\nexport const indexesAtom = atom<any[]>([]);\nexport const selectedRowAtom = atom<any>({});\nexport const tableFieldValuesAtom = atom<Array<{ label: string; value: string }>>([]);\n\nexport const pageAtom = atom<number>(1);\nexport const pageSizeAtom = atomWithStorage<number>('discover-pagination-size', 50);\n\n// Surrounding Data Atoms\nexport const surroundingDataFilterAtom = atom<DataFilterType[]>([]);\nexport const beforeTimeFieldPageSizeAtom = atom<number>(5);\nexport const afterTimeFieldPageSizeAtom = atom<number>(5);\nexport const beforeTimeAtom = atom<string>('');\nexport const afterTimeAtom = atom<string>('');\nexport const beforeCountAtom = atom<number>(0);\nexport const afterCountAtom = atom<number>(0);\nexport const surroundingTableFieldsAtom = atom<any[]>([]);\nexport const surroundingSelectedFieldsAtom = atom<any[]>([]);\n\nexport const datasourcesAtom = atom<Array<DataSourceInstanceSettings<DataSourceJsonData>>>([]);\nexport const selectedDatasourceAtom = atom<DataSourceInstanceSettings<DataSourceJsonData>>();\nexport const timeRangeAtom = atom<any>({\n    from: DISCOVER_SHORTCUTS[2].range()[0].toDate(),\n    to: DISCOVER_SHORTCUTS[2].range()[1].toDate(),\n    raw: DISCOVER_SHORTCUTS[2].raw,\n});\n\n\nexport const discoverLoadingAtom = atom({\n    getTableData: false,\n    getTopData: false,\n    getSurroundingData: false,\n    getTableDataCharts: false,\n    getTableFieldValues: false,\n    getIndexes: false,\n    getTimeFields: false,\n    getTableFields: false,\n});\n","import dayjs, { Dayjs, ManipulateType } from \"dayjs\";\n\nexport interface QueryTableDataParams {\n    catalog: string;\n    database: string;\n    table: string;\n    cluster: string;\n    startDate: string;\n    endDate: string;\n    sort: string;\n    timeField: string;\n    data_filters: any[];\n    interval?: IntervalEnum;\n    interval_value?: number;\n    search_type: string;\n    search_value: string;\n    indexes?: string;\n    indexes_statement?: string;\n    page: string;\n    page_size: number;\n    lucene_where?: string;\n}\n\n\nexport interface SurroundingParams {\n    catalog: string;\n    database: string;\n    table: string;\n    cluster: string;\n    timeField: string;\n    time: string;\n    data_filters: any;\n    pageSize: string;\n    operator: '>' | '<';\n    theme: string | undefined;\n}\n\nexport interface DataFilterType {\n    fieldName: string;\n    operator: Operator;\n    value: Array<string | number>;\n    label?: string;\n    id: string;\n}\n\nexport type Operator =\n    | '='\n    | '!='\n    | 'in'\n    | 'not in'\n    | 'is null'\n    | 'is not null'\n    | 'between'\n    | 'not between'\n    | 'like'\n    | 'not like'\n    | 'match_all'\n    | 'match_any'\n    | 'match_phrase'\n    | 'match_phrase_prefix';\n\nexport interface DiscoverCurrent {\n    catalog: string;\n    database: string;\n    table: string;\n    cluster: string;\n    timeField: string;\n    date: [Dayjs, Dayjs] | [];\n}\n\nexport enum IntervalEnum {\n    Auto = 'auto',\n    Day = 'day',\n    Week = 'week',\n    Month = 'month',\n    Year = 'year',\n    Hour = 'hour',\n    Minute = 'minute',\n    Second = 'second',\n}\n\n\nexport type ShortcutItem = {\n    key: string;\n    text: string;\n    label: string;\n    range: (now?: dayjs.Dayjs) => dayjs.Dayjs[];\n    format: string;\n    type: string;\n    number: number;\n}\n\nexport interface QueryTableFieldsParams {\n    catalog: string;\n    database: string;\n    table: string;\n    describe_extend_variant_column?: string;\n}\n\nexport type FieldNode = {\n    name: string;\n    type: string;\n    children?: FieldNode[];\n    Null?: string;\n    Key?: string;\n    Default?: string | null;\n    Extra?: string;\n    Comment?: string;\n    Visible?: string;\n};\n\n\nexport interface RequestParams {\n    catalog: string;\n    database: string;\n    table: string;\n    describe_extend_variant_column?: boolean;\n}\n\nexport interface QueryTableIndexesParams {\n    catalog: string;\n    database: string;\n    table: string\n}\n\nexport interface QueryTableParams {\n    catalog: string;\n    database: string;\n}\n\nexport type AutoInterval = {\n    current_date_range: number;\n    current_type: ManipulateType;\n    interval_unit: ManipulateType;\n    interval_value: number;\n};\n\n\nexport type Frame = {\n    schema: {\n        fields: Array<{ name: string }>;\n    };\n    data: {\n        values: any[][];\n    };\n};\n\nexport type Result = {\n    frames: Frame[];\n};\n\nexport type Root = {\n    results: Record<string, Result>;\n};\n\nexport type QueryTracesParams = {\n    database: string;\n    table: string;\n    timeField: string;\n    startDate: string;\n    endDate: string;\n    service_name?: string;\n    operation?: string;\n    statusCode?: string;\n    minDuration?: string;\n    maxDuration?: string;\n    tags?: string;\n    page?: number;\n    page_size?: number;\n    sortBy?: string;\n};\n\nexport type TracesServicesParams = {\n  table: string;\n  timeField: string;\n  startDate: string;\n  endDate: string;\n};\n\nexport type TracesOperationsParams = {\n  table: string;\n  timeField: string;\n  startDate: string;\n  endDate: string;\n  service_name: string;\n};\n","import { toDataFrame } from '@grafana/data';\nimport { getBackendSrv } from '@grafana/runtime';\nimport { lastValueFrom } from 'rxjs';\n\ntype GetColumnParams = {\n    connectionId: string;\n    database: string;\n    table: string;\n    column: string;\n    datasourceType?: string;\n};\n\ntype ColumnMetadata = {\n    name: string;\n    dataType?: string;\n    columnType?: string;\n};\n\ntype GetIndexesParams = {\n    connectionId: string;\n    database: string;\n    table: string;\n    datasourceType?: string;\n};\n\nconst escapeSqlLiteral = (value: string) => value.replace(/'/g, \"''\");\n\nconst normalizeColumnType = ({ dataType, columnType }: { dataType?: string; columnType?: string }): string => {\n    const source = (columnType || dataType || '').trim();\n    if (!source) {\n        return '';\n    }\n\n    const lower = source.toLowerCase();\n\n    if (lower.startsWith('nullable(') && lower.endsWith(')')) {\n        const inner = source.slice(9, -1);\n        const normalizedInner = normalizeColumnType({ dataType: inner, columnType: undefined });\n        return normalizedInner ? `Nullable(${normalizedInner})` : source;\n    }\n\n    if (lower.startsWith('map')) {\n        return source.replace(/^map/i, 'Map');\n    }\n\n    if (lower.startsWith('array')) {\n        return source.replace(/^array/i, 'Array');\n    }\n\n    if (lower.startsWith('json') || lower.startsWith('variant')) {\n        return 'JSON';\n    }\n\n    if (lower === 'bool' || lower === 'boolean' || lower.startsWith('tinyint(1)')) {\n        return 'Bool';\n    }\n\n    if (lower.startsWith('tinyint')) {\n        return 'Int8';\n    }\n\n    if (lower.startsWith('smallint')) {\n        return 'Int16';\n    }\n\n    if (lower.startsWith('mediumint')) {\n        return 'Int32';\n    }\n\n    if (lower.startsWith('bigint') || lower.startsWith('int') || lower.startsWith('integer')) {\n        return 'Int64';\n    }\n\n    if (lower.startsWith('float') || lower.startsWith('double') || lower.startsWith('real')) {\n        return 'Float64';\n    }\n\n    if (lower.startsWith('decimal') || lower.startsWith('numeric')) {\n        return 'Float64';\n    }\n\n    if (lower.startsWith('date')) {\n        return source.replace(/^date/i, 'Date');\n    }\n\n    if (lower.startsWith('timestamp') || lower.startsWith('datetime')) {\n        return 'DateTime';\n    }\n\n    if (lower.startsWith('enum')) {\n        return source.replace(/^enum/i, 'Enum');\n    }\n\n    if (lower.startsWith('uuid')) {\n        return 'UUID';\n    }\n\n    if (lower.startsWith('ipv4')) {\n        return 'IPv4';\n    }\n\n    if (lower.startsWith('ipv6')) {\n        return 'IPv6';\n    }\n\n    if (lower.startsWith('tuple')) {\n        return source.replace(/^tuple/i, 'Tuple');\n    }\n\n    if (lower.startsWith('struct')) {\n        return source.replace(/^struct/i, 'Tuple');\n    }\n\n    if (lower.startsWith('char') || lower.startsWith('varchar') || lower.startsWith('text') || lower.startsWith('string')) {\n        return 'String';\n    }\n\n    return source;\n};\n\nexport async function getColumn({\n    connectionId,\n    database,\n    table,\n    column,\n    datasourceType = 'mysql',\n}: GetColumnParams): Promise<(ColumnMetadata & { normalizedType: string }) | null> {\n    if (!connectionId || !database || !table || !column) {\n        return null;\n    }\n\n    const query = `\nSELECT\n  COLUMN_NAME AS Field,\n  DATA_TYPE AS DataType,\n  COLUMN_TYPE AS ColumnType\nFROM information_schema.COLUMNS\nWHERE TABLE_SCHEMA = '${escapeSqlLiteral(database)}'\n  AND TABLE_NAME = '${escapeSqlLiteral(table)}'\n  AND COLUMN_NAME = '${escapeSqlLiteral(column)}'\nLIMIT 1;\n`;\n\n    const response$ = getBackendSrv().fetch({\n        url: '/api/ds/query',\n        method: 'POST',\n        data: {\n            queries: [\n                {\n                    refId: 'getColumn',\n                    datasource: { type: datasourceType, uid: connectionId },\n                    rawSql: query,\n                    format: 'table',\n                },\n            ],\n        },\n    });\n\n    try {\n        const { data, ok } = await lastValueFrom(response$);\n        if (!ok) {\n            return null;\n        }\n\n        const resultData = data as { results?: Record<string, any> };\n        const frame = resultData?.results?.getColumn?.frames?.[0];\n        if (!frame) {\n            return null;\n        }\n\n        const dataFrame = toDataFrame(frame);\n        const nameField = dataFrame.fields.find(field => field.name === 'Field') ?? dataFrame.fields[0];\n        const dataTypeField = dataFrame.fields.find(field => field.name === 'DataType');\n        const columnTypeField = dataFrame.fields.find(field => field.name === 'ColumnType');\n\n        const name = nameField?.values?.get?.(0);\n        if (!name) {\n            return null;\n        }\n\n        const dataTypeValue = dataTypeField?.values?.get?.(0);\n        const columnTypeValue = columnTypeField?.values?.get?.(0);\n\n        const columnInfo: ColumnMetadata = {\n            name: String(name),\n            dataType: dataTypeValue != null ? String(dataTypeValue) : undefined,\n            columnType: columnTypeValue != null ? String(columnTypeValue) : undefined,\n        };\n\n        const normalizedType = normalizeColumnType({\n            dataType: columnInfo.dataType,\n            columnType: columnInfo.columnType,\n        });\n\n        return {\n            ...columnInfo,\n            normalizedType,\n        };\n    } catch (error) {\n        console.error('Failed to fetch column metadata', error);\n        return null;\n    }\n}\n\nexport async function getInvertedIndexColumns({\n    connectionId,\n    database,\n    table,\n    datasourceType = 'mysql',\n}: GetIndexesParams): Promise<string[]> {\n    if (!connectionId || !database || !table) {\n        return [];\n    }\n\n    const query = `SHOW INDEXES FROM \\`${database}\\`.\\`${table}\\``;\n\n    const response$ = getBackendSrv().fetch({\n        url: '/api/ds/query',\n        method: 'POST',\n        data: {\n            queries: [\n                {\n                    refId: 'getInvertedIndexes',\n                    datasource: { type: datasourceType, uid: connectionId },\n                    rawSql: query,\n                    format: 'table',\n                },\n            ],\n        },\n    });\n\n    try {\n        const { data, ok } = await lastValueFrom(response$);\n        if (!ok) {\n            return [];\n        }\n\n        const resultData = data as { results?: Record<string, any> };\n        const frame =\n            resultData?.results?.getInvertedIndexes?.frames?.[0] ??\n            resultData?.results?.getIndexes?.frames?.[0];\n\n        if (!frame) {\n            return [];\n        }\n\n        const dataFrame = toDataFrame(frame);\n        const columnNameField =\n            dataFrame.fields.find(field => field.name === 'Column_name') ??\n            dataFrame.fields.find(field => field.name === 'COLUMN_NAME');\n        const indexTypeField =\n            dataFrame.fields.find(field => field.name === 'Index_type') ??\n            dataFrame.fields.find(field => field.name === 'INDEX_TYPE');\n\n        if (!columnNameField || !indexTypeField) {\n            return [];\n        }\n\n        const columnNames = Array.from(columnNameField.values ?? []);\n        const indexTypes = Array.from(indexTypeField.values ?? []);\n        const indexedColumns = new Set<string>();\n\n        for (let i = 0; i < columnNames.length; i += 1) {\n            const columnName = columnNames[i];\n            const indexType = indexTypes[i];\n            if (typeof columnName !== 'string' || columnName.length === 0) {\n                continue;\n            }\n            if (typeof indexType !== 'string') {\n                continue;\n            }\n\n            if (indexType.toUpperCase().includes('INVERT')) {\n                indexedColumns.add(columnName);\n            }\n        }\n\n        return Array.from(indexedColumns);\n    } catch (error) {\n        console.error('Failed to fetch inverted index metadata', error);\n        return [];\n    }\n}\n\n\nexport function getDatabases(selectdbDS: any) {\n    const response$ = getBackendSrv().fetch({\n        url: '/api/ds/query',\n        method: 'POST',\n        data: {\n            queries: [\n                {\n                    refId: 'getDatabases',\n                    datasource: {\n                        type: 'mysql',\n                        uid: selectdbDS.uid,\n                    },\n                    rawSql: 'SHOW DATABASES',\n                    format: 'table',\n                },\n            ],\n        },\n    });\n    return response$;\n}\n\nexport function getTablesService({ selectdbDS, database }: { selectdbDS: any; database: string }) {\n    return getBackendSrv().fetch({\n        url: '/api/ds/query',\n        method: 'POST',\n        data: {\n            queries: [\n                {\n                    refId: 'getTables',\n                    datasource: { type: 'mysql', uid: selectdbDS.uid },\n                    rawSql: `SHOW TABLES FROM \\`${database}\\``,\n                    format: 'table',\n                },\n            ],\n        },\n    });\n}\n\nexport function getFieldsService({ selectdbDS, database, table }: { selectdbDS: any; database: string; table: string }) {\n    return getBackendSrv().fetch({\n        url: '/api/ds/query',\n        method: 'POST',\n        data: {\n            queries: [\n                {\n                    refId: 'getFields',\n                    datasource: { type: 'mysql', uid: selectdbDS.uid },\n                    rawSql: `SHOW COLUMNS FROM \\`${database}\\`.\\`${table}\\``,\n                    format: 'table',\n                },\n            ],\n        },\n    });\n}\n\nexport function getColumnFromFieldService({ selectdbDS, database, table }: { selectdbDS: any; database: string; table: string }) {\n    // return getBackendSrv().fetch({\n    //     url: '/api/ds/query',\n    //     method: 'POST',\n    //     data: {\n    //         queries: [\n    //             {\n    //                 refId: 'getColumnFromFieldService',\n    //                 datasource: { type: 'mysql', uid: selectdbDS.uid },\n    //                 rawSql: `SHOW COLUMNS FROM \\`${database}\\`.\\`${table}\\``,\n    //                 format: 'table',\n    //             },\n    //         ],\n    //     },\n    // });\n}\n\nexport function getIndexesService({ selectdbDS, database, table }: { selectdbDS: any; database: string; table: string }) {\n    return getBackendSrv().fetch({\n        url: '/api/ds/query',\n        method: 'POST',\n        data: {\n            queries: [\n                {\n                    refId: 'getIndexes',\n                    datasource: { type: 'mysql', uid: selectdbDS.uid },\n                    rawSql: `SHOW INDEXES FROM \\`${database}\\`.\\`${table}\\``,\n                    format: 'table',\n                },\n            ],\n        },\n    });\n}\n","// --- stable stringify: 递归排序键，避免循环引用导致崩溃 ---\nfunction stableStringify(value: any): string {\n    const seen = new WeakSet();\n\n    const recur = (v: any): string => {\n        if (v === null) {\n            return 'null';\n        }\n        const t = typeof v;\n        if (t === 'number') {\n            return Number.isFinite(v) ? String(v) : 'null';\n        }\n        if (t === 'boolean') {\n            return v ? 'true' : 'false';\n        }\n        if (t === 'string') {\n            return JSON.stringify(v);\n        }\n        if (t === 'bigint') {\n            return JSON.stringify(v.toString());\n        }\n        if (t === 'undefined' || t === 'function' || t === 'symbol') {\n            return 'null';\n        }\n\n        // object / array\n        if (seen.has(v)) {\n            return '\"[Circular]\"';\n        }\n        seen.add(v);\n\n        if (Array.isArray(v)) {\n            return '[' + v.map(recur).join(',') + ']';\n        }\n\n        const keys = Object.keys(v).sort();\n        const body = keys.map(k => JSON.stringify(k) + ':' + recur(v[k])).join(',');\n        return '{' + body + '}';\n    };\n\n    return recur(value);\n}\n\n// --- 小工具 ---\nfunction u8ToHex(u8: Uint8Array): string {\n    let out = '';\n    for (let i = 0; i < u8.length; i++) {\n        out += u8[i].toString(16).padStart(2, '0');\n    }\n    return out;\n}\n\nfunction hasSubtle(): boolean {\n    return typeof window !== 'undefined' && !!window.crypto && !!window.isSecureContext && typeof window.crypto.subtle?.digest === 'function';\n}\n\n// --- 纯 JS 的 SHA-256 fallback（简实现，无依赖） ---\nfunction sha256HexJS(data: Uint8Array): string {\n    // 常量\n    const K = new Uint32Array([\n        0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe,\n        0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7,\n        0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b,\n        0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070, 0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,\n        0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,\n    ]);\n\n    // 初始哈希\n    let h0 = 0x6a09e667,\n        h1 = 0xbb67ae85,\n        h2 = 0x3c6ef372,\n        h3 = 0xa54ff53a,\n        h4 = 0x510e527f,\n        h5 = 0x9b05688c,\n        h6 = 0x1f83d9ab,\n        h7 = 0x5be0cd19;\n\n    // 预处理：填充\n    const l = data.length;\n    const bitLenHi = (l >>> 29) >>> 0;\n    const bitLenLo = (l << 3) >>> 0;\n    const nBlocks = (((l + 9) >> 6) + 1) << 4; // 以 16 个 32bit 为一组\n    const M = new Uint32Array(nBlocks);\n\n    for (let i = 0; i < l; i++) {\n        M[i >> 2] |= data[i] << ((3 - (i & 3)) << 3);\n    }\n    M[l >> 2] |= 0x80 << ((3 - (l & 3)) << 3);\n    M[nBlocks - 2] = bitLenHi;\n    M[nBlocks - 1] = bitLenLo;\n\n    const W = new Uint32Array(64);\n\n    const rotr = (x: number, n: number) => (x >>> n) | (x << (32 - n));\n    for (let i = 0; i < nBlocks; i += 16) {\n        for (let t = 0; t < 16; t++) {\n            W[t] = M[i + t];\n        }\n        for (let t = 16; t < 64; t++) {\n            const s0 = (rotr(W[t - 15], 7) ^ rotr(W[t - 15], 18) ^ (W[t - 15] >>> 3)) >>> 0;\n            const s1 = (rotr(W[t - 2], 17) ^ rotr(W[t - 2], 19) ^ (W[t - 2] >>> 10)) >>> 0;\n            W[t] = (W[t - 16] + s0 + W[t - 7] + s1) >>> 0;\n        }\n\n        let a = h0,\n            b = h1,\n            c = h2,\n            d = h3,\n            e = h4,\n            f = h5,\n            g = h6,\n            h = h7;\n\n        for (let t = 0; t < 64; t++) {\n            const S1 = (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) >>> 0;\n            const ch = ((e & f) ^ (~e & g)) >>> 0;\n            const T1 = (h + S1 + ch + K[t] + W[t]) >>> 0;\n            const S0 = (rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) >>> 0;\n            const maj = ((a & b) ^ (a & c) ^ (b & c)) >>> 0;\n            const T2 = (S0 + maj) >>> 0;\n\n            h = g;\n            g = f;\n            f = e;\n            e = (d + T1) >>> 0;\n            d = c;\n            c = b;\n            b = a;\n            a = (T1 + T2) >>> 0;\n        }\n\n        h0 = (h0 + a) >>> 0;\n        h1 = (h1 + b) >>> 0;\n        h2 = (h2 + c) >>> 0;\n        h3 = (h3 + d) >>> 0;\n        h4 = (h4 + e) >>> 0;\n        h5 = (h5 + f) >>> 0;\n        h6 = (h6 + g) >>> 0;\n        h7 = (h7 + h) >>> 0;\n    }\n\n    const out = new Uint8Array(32);\n    const H = [h0, h1, h2, h3, h4, h5, h6, h7];\n    for (let i = 0; i < 8; i++) {\n        out[i * 4 + 0] = (H[i] >>> 24) & 0xff;\n        out[i * 4 + 1] = (H[i] >>> 16) & 0xff;\n        out[i * 4 + 2] = (H[i] >>> 8) & 0xff;\n        out[i * 4 + 3] = H[i] & 0xff;\n    }\n    return u8ToHex(out);\n}\n\n// --- 通用 SHA-256（浏览器优先，fallback 到纯 JS） ---\nasync function sha256Hex(input: string): Promise<string> {\n    const data = new TextEncoder().encode(input);\n    if (hasSubtle()) {\n        const buf = await window.crypto.subtle.digest('SHA-256', data);\n        return u8ToHex(new Uint8Array(buf));\n    }\n    // 非 https 或老环境：走纯 JS\n    return sha256HexJS(data);\n}\n\n// --- 你的两个导出函数 ---\nexport async function generateUid(obj: any) {\n    const json = stableStringify(obj);\n    return sha256Hex(json);\n}\n\nexport async function generateTableDataUID(items: any[]) {\n    // 允许 _original 缺失时退回整个 item；并发计算，更快\n    const sources = items.map(it => (it && it._original) ?? it);\n    const uids = await Promise.all(sources.map(generateUid));\n    return items.map((it, i) => ({ ...it, _uid: uids[i] }));\n}\n\n\nexport function isIgnorableHighlightToken(token: string): boolean {\n    const ignoreChars = new Set([\n        ',',\n        '.',\n        ';',\n        ':',\n        '(',\n        ')',\n        '{',\n        '}',\n        '[',\n        ']',\n        '+',\n        '-',\n        '*',\n        '/',\n        '=',\n        '<',\n        '>',\n        '!',\n        '?',\n        '|',\n        '&',\n        '%',\n        '^',\n        '$',\n        '#',\n        '@',\n        '~',\n        '`',\n        '\\\\',\n        \"'\",\n        '\"',\n    ]);\n    // 全是空格或换行\n    if (!token.trim()) {return true;}\n    // 单个字符且在 ignoreChars 中\n    if (token.length === 1 && ignoreChars.has(token)) {return true;}\n    // 多个字符但全是标点符号\n    if (/^[\\u2000-\\u206F\\u2E00-\\u2E7F!\"#$%&'()*+,\\-./:;<=>?@[\\\\\\]^_`{|}~]+$/.test(token)) {\n        return true;\n    }\n\n    return false;\n}\n\nexport function trimSpacesAroundEquals(str: string) {\n  // 去掉等于号两边所有空格\n  return str.replace(/\\s*=\\s*/g, '=');\n}\n\n","import { getAutoInterval } from '../constants';\nimport dayjs, { Dayjs, ManipulateType } from 'dayjs';\nimport { flatten, orderBy, some } from 'lodash-es';\nimport { nanoid } from 'nanoid';\nimport { DiscoverCurrent, DataFilterType, AutoInterval, IntervalEnum } from 'types/type';\nimport jsTokens from 'js-tokens';\nimport localeData from 'dayjs/plugin/localeData';\nimport { DataFrame, FieldType } from '@grafana/data';\nimport utc from 'dayjs/plugin/utc';\nimport { isIgnorableHighlightToken } from './utils';\ndayjs.extend(utc);\ndayjs.extend(localeData);\n\nexport const OPERATORS: string[] = [\n    '=',\n    '!=',\n    'in',\n    'not in',\n    'is null',\n    'is not null',\n    'like',\n    'not like',\n    'between',\n    'not between',\n    'match_any',\n    'match_all',\n    'match_phrase',\n    'match_phrase_prefix',\n];\nexport const SQL_OPERATORS: string[] = ['=', '!=', '>', '<', '>=', '<=', 'LIKE', 'IN', 'AND', 'OR', 'BETWEEN'];\nexport const TIME_FIELD_TYPES = ['DATETIME', 'DATE', 'DATETIMEV2', 'DATEV2', 'TIME'];\nexport function isValidTimeFieldType(fieldType: string): boolean {\n    // 提取基础字段类型（移除括号及其内容）\n    const baseFieldType = fieldType.split('(')[0];\n    return TIME_FIELD_TYPES.includes(baseFieldType);\n}\nexport const CAN_SEARCH_FIELD_TYPE = ['STRING', 'ARRAY', 'NUMBER', 'VARIANT'];\nexport const ENABLE_SEARCH_FIELD_TYPE = ['DATETIME', 'TIMESTAMP', 'TIME'];\nexport const getFieldType = (columnType: string | undefined) => {\n    if (!columnType) {\n        return '';\n    }\n    const currentColumnType = FIELD_TYPES.find(item => item.value.some(val => columnType.toLocaleUpperCase().includes(val)));\n    return currentColumnType?.key;\n};\n\nexport const DISCOVER_DEFAULT_STATUS: DiscoverCurrent = {\n    catalog: 'internal',\n    database: '',\n    table: '',\n    cluster: '',\n    timeField: '',\n    date: [],\n};\n\nexport enum SearchableEnum {\n    ANY = 'ANY',\n    YES = 'YES',\n    NO = 'NO',\n}\nexport enum AggregatableEnum {\n    ANY = 'ANY',\n    YES = 'YES',\n    NO = 'NO',\n}\n\nexport const SEARCHABLE = [\n    {\n        label: `Any`,\n        value: SearchableEnum.ANY,\n    },\n    {\n        label: 'Yes',\n        value: SearchableEnum.YES,\n    },\n    {\n        label: 'No',\n        value: SearchableEnum.NO,\n    },\n];\n\nexport const AGGREGATABLE = [\n    {\n        label: `Any`,\n        value: AggregatableEnum.ANY,\n    },\n    {\n        label: 'Yes',\n        value: AggregatableEnum.YES,\n    },\n    {\n        label: 'No',\n        value: AggregatableEnum.NO,\n    },\n];\n\nexport enum FieldTypeEnum {\n    ANY = 'ANY',\n    STRING = 'STRING',\n    NUMBER = 'NUMBER',\n    DATE = 'DATE',\n}\n\nexport enum ParamsKeyEnum {\n    sqlCatalog = 'sqlCatalog',\n    sqlDatabase = 'sqlDatabase',\n    startDate = 'startDateRange',\n    endDate = 'endDateRange',\n    sqlSearch = 'sqlSearch',\n    selectedTable = 'selectedTable',\n    dateInterval = 'dateInterval',\n    selectedField = 'selectedField',\n    dataFilter = 'dataFilter',\n    selectedTimeField = 'selectedTimeField',\n    sortedField = 'sortedField',\n    searchType = 'searchType',\n    selectedIndex = 'selectedIndex',\n    selectedCluster = 'selectedCluster',\n}\n\nexport function getFilterSQL({ fieldName, operator, value }: DataFilterType): string {\n    const valueString = value.map((e: any) => {\n        if (typeof e === 'string') {\n            return `'${e}'`;\n        } else {\n            return e;\n        }\n    });\n\n    if (\n        operator === '=' ||\n        operator === '!=' ||\n        operator === 'like' ||\n        operator === 'not like' ||\n        operator === 'match_all' ||\n        operator === 'match_any' ||\n        operator === 'match_phrase' ||\n        operator === 'match_phrase_prefix'\n    ) {\n        return `\\`${fieldName}\\` ${operator} ${valueString[0]}`;\n    }\n\n    if (operator === 'is null' || operator === 'is not null') {\n        return `\\`${fieldName}\\` ${operator}`;\n    }\n\n    if (operator === 'between' || operator === 'not between') {\n        return `\\`${fieldName}\\` ${operator} ${valueString[0]} AND ${valueString[1]}`;\n    }\n\n    if (operator === 'in' || operator === 'not in') {\n        return `\\`${fieldName}\\` ${operator} (${valueString})`;\n    }\n\n    return '';\n}\n\nexport function addSqlFilter(sql: string, dataFilterValue: DataFilterType): string {\n    let result = sql;\n    if (!sql.toUpperCase().includes('WHERE')) {\n        result += ' WHERE';\n    } else {\n        result += ' AND';\n    }\n\n    result += ` (${getFilterSQL(dataFilterValue)})`;\n\n    return result;\n}\n\nfunction isWrappedInQuotes(inputString: string): boolean {\n    const pattern = /([\"'])(.*?)\\1/;\n    return pattern.test(inputString);\n}\n\nexport function getIndexesStatement(indexes: any[], allField: any[], keywords: string) {\n    let operator: 'MATCH_ANY' | 'MATCH_PHRASE' | 'MATCH_PHRASE_PREFIX' | '=' = 'MATCH_ANY';\n\n    let searchValue = keywords.trim();\n\n    if (!searchValue || !indexes) {\n        return '';\n    }\n\n    if (isWrappedInQuotes(keywords)) {\n        operator = 'MATCH_PHRASE';\n    } else {\n        searchValue = `'${searchValue}'`;\n    }\n    const indexesNames = indexes.map(item => item.columnName);\n    return indexesNames.reduce((prevValue, currValue) => {\n        const currentField = allField.find(field => `${field.value}` === currValue);\n        const currentFieldType = getFieldType(currentField.Type)?.toUpperCase();\n        if (currentFieldType === 'NUMBER') {\n            operator = '=';\n        }\n        if (currentFieldType === 'STRING' || currentFieldType === 'ARRAY') {\n            if (isWrappedInQuotes(keywords)) {\n                operator = 'MATCH_PHRASE';\n            } else {\n                operator = 'MATCH_ANY';\n            }\n        }\n        const canSearchField = CAN_SEARCH_FIELD_TYPE.includes(currentFieldType as string);\n        if (canSearchField) {\n            if (prevValue) {\n                return `${prevValue} OR \\`${currValue}\\` ${operator} ${searchValue}`;\n            } else {\n                return `\\`${currValue}\\` ${operator} ${searchValue}`;\n            }\n        }\n        return prevValue;\n    }, '');\n}\n\nexport const DISCOVER_SHORTCUTS = [\n    {\n        key: nanoid(),\n        text: `Last 5 Minutes`,\n        label: `Last 5 Minutes`,\n        range: (now: dayjs.Dayjs = dayjs()) => [now.add(-5, 'minute').startOf('second'), now],\n        format: 'HH:mm',\n        raw: {\n            from: 'now-5m',\n            to: 'now',\n        },\n        type: 'minute',\n        number: -5,\n    },\n    {\n        key: nanoid(),\n        text: `Last 15 Minutes`,\n        label: `Last 15 Minutes`,\n        raw: {\n            from: 'now-15m',\n            to: 'now',\n        },\n        range: (now: dayjs.Dayjs = dayjs()) => [now.add(-15, 'minute').startOf('second'), now],\n        format: 'HH:mm',\n        type: 'minute',\n        number: -15,\n    },\n    {\n        key: nanoid(),\n        text: `Last 1 Hour`,\n        label: `Last 1 Hour`,\n        raw: {\n            from: 'now-1h',\n            to: 'now',\n        },\n        range: (now: dayjs.Dayjs = dayjs()) => [now.add(-1, 'hour').startOf('second'), now],\n        format: 'HH:mm',\n        type: 'hour',\n        number: -1,\n    },\n    {\n        key: nanoid(),\n        text: `Last 1 Day`,\n        label: `Last 1 Day`,\n        raw: {\n            from: 'now-1d',\n            to: 'now',\n        },\n        range: (now: dayjs.Dayjs = dayjs()) => [now.add(-1, 'day').startOf('second'), now],\n        format: 'HH:mm',\n        type: 'day',\n        number: -1,\n    },\n    {\n        key: nanoid(),\n        text: `Last 7 Days`,\n        label: `Last 1 Days`,\n        raw: {\n            from: 'now-7d',\n            to: 'now',\n        },\n        range: (now: dayjs.Dayjs = dayjs()) => [now.add(-7, 'day').startOf('second'), now],\n        format: 'HH:mm',\n        type: 'day',\n        number: -7,\n    },\n    {\n        key: nanoid(),\n        text: `Last 1 Month`,\n        label: `Last 1 Month`,\n        raw: {\n            from: 'now-1M',\n            to: 'now',\n        },\n        range: (now: dayjs.Dayjs = dayjs()) => [now.add(-1, 'month').startOf('second'), now],\n        format: 'HH:mm',\n        type: 'month',\n        number: -1,\n    },\n    {\n        key: nanoid(),\n        text: `Last 3 Months`,\n        label: `Last 3 Months`,\n        raw: {\n            from: 'now-3M',\n            to: 'now',\n        },\n        range: (now: dayjs.Dayjs = dayjs()) => [now.add(-3, 'month').startOf('second'), now],\n        format: 'HH:mm',\n        type: 'month',\n        number: -3,\n    },\n    {\n        key: nanoid(),\n        text: `Last 1 Year`,\n        label: `Last 1 Year`,\n        raw: {\n            from: 'now-1y',\n            to: 'now',\n        },\n        range: (now: dayjs.Dayjs = dayjs()) => [now.add(-1, 'year').startOf('second'), now],\n        format: 'HH:mm',\n        type: 'year',\n        number: -1,\n    },\n];\n\nexport const SURROUNDING_LOGS_OPERATORS = [\n    {\n        label: '5',\n        value: '5',\n    },\n    {\n        label: '10',\n        value: '10',\n    },\n];\n\nexport function getLatestTime(id: string) {\n    if (!id) {\n        return null;\n    }\n    const selectedItem = DISCOVER_SHORTCUTS.find(item => item.key === id);\n    return selectedItem?.range();\n}\n\nexport const TIME_INTERVALS = [\n    {\n        value: 'auto',\n        label: `Auto`,\n    },\n    {\n        value: 'second',\n        label: `Second`,\n    },\n    {\n        value: 'minute',\n        label: `Minute`,\n    },\n    {\n        value: 'hour',\n        label: `Hour`,\n    },\n    {\n        value: 'day',\n        label: `Day`,\n    },\n    {\n        value: 'week',\n        label: `Week`,\n    },\n    {\n        value: 'month',\n        label: `Month`,\n    },\n    {\n        value: 'year',\n        label: `Year`,\n    },\n];\n\nexport const PAGESIZE_OPTIONS = [10, 20, 50, 100, 200];\n\nexport const FIELD_TYPES = [\n    {\n        key: 'STRING',\n        value: ['VARCHAR', 'STRING', 'CHAR', 'TEXT'],\n        icon: '',\n    },\n    {\n        key: 'NUMBER',\n        value: ['INT', 'LARGEINT', 'SMALLINT', 'TINYINT', 'DECIMAL', 'BIGINT', 'FLOAT', 'DOUBLE'],\n        icon: '',\n    },\n    {\n        key: 'DATE',\n        value: ['DATE', 'DATETIME', 'DATEV2', 'DATETIMEV2'],\n        icon: '',\n    },\n    {\n        key: 'JSONB',\n        value: ['JSONB'],\n        icon: '',\n        complex: true,\n    },\n    {\n        key: 'ARRAY',\n        value: ['ARRAY'],\n        icon: '',\n        complex: true,\n    },\n    {\n        key: 'BOOLEAN',\n        value: ['BOOLEAN'],\n        icon: '',\n    },\n    {\n        key: 'BITMAP',\n        value: ['BITMAP'],\n        icon: '',\n        complex: true,\n    },\n    {\n        key: 'HLL',\n        value: ['HLL'],\n        icon: '',\n        complex: true,\n    },\n    {\n        key: 'VARIANT',\n        value: ['VARIANT'],\n        icon: '',\n        complex: true,\n    },\n    {\n        key: 'JSON',\n        value: ['JSON'],\n        icon: '',\n        complex: true,\n    },\n];\n\nexport function encodeBase64(str: string) {\n    return btoa(encodeURIComponent(str).replace(/%([0-9A-F]{2})/g, (match, p1) => String.fromCharCode(parseInt('0x' + p1, 10))));\n}\n\nexport function decodeBase64(base64: string) {\n    return decodeURIComponent(\n        Array.from(atob(base64))\n            .map(c => '%' + c.charCodeAt(0).toString(16).padStart(2, '0'))\n            .join(''),\n    );\n}\n\nexport const isComplexType = (columnType: string | undefined) => {\n    if (!columnType) {\n        return false;\n    }\n    const currentColumnType = FIELD_TYPES.find(item => item.value.some(val => columnType.toLocaleUpperCase().includes(val)));\n    if (currentColumnType) {\n        return !!currentColumnType.complex;\n    }\n    return true;\n};\n\nexport function formatDate(interval: ManipulateType) {\n    let date_format = 'YYYY-MM-DD HH:mm:ss';\n    switch (interval) {\n        case 'year':\n            date_format = 'YYYY';\n            break;\n        case 'month':\n            date_format = 'YYYY-MM';\n            break;\n        case 'week':\n            date_format = 'YYYY-MM-DD';\n            break;\n        case 'day':\n            date_format = 'YYYY-MM-DD';\n            break;\n        case 'hour':\n            date_format = 'YYYY-MM-DD HH:mm:ss';\n            break;\n        case 'minute':\n            date_format = 'YYYY-MM-DD HH:mm:ss';\n            break;\n        case 'second':\n        default:\n            date_format = 'YYYY-MM-DD HH:mm:ss';\n            break;\n    }\n    return date_format;\n}\n\nexport function resetDate(date: Dayjs, interval: ManipulateType) {\n    let date_reset = date;\n    switch (interval) {\n        case 'year':\n            date_reset.set('month', 1).set('date', 1).set('hour', 0).set('minute', 0).set('second', 0);\n            break;\n        case 'month':\n            date_reset.set('date', 1).set('hour', 0).set('minute', 0).set('second', 0);\n            break;\n        case 'week':\n            date_reset.set('hour', 0).set('minute', 0).set('second', 0);\n            break;\n        case 'day':\n            date_reset.set('hour', 0).set('minute', 0).set('second', 0);\n            break;\n        case 'hour':\n            date_reset.set('minute', 0).set('second', 0);\n            break;\n        case 'minute':\n            date_reset.set('second', 0);\n            break;\n        case 'second':\n        default:\n            break;\n    }\n    return date_reset;\n}\n\nexport function getDateRange(startDate: Dayjs, endDate: Dayjs, interval: any) {\n    const DATE_FORMAT = formatDate(interval.interval_unit);\n    if (dayjs(startDate, DATE_FORMAT).isSame(dayjs(endDate, DATE_FORMAT), interval.interval_unit)) {\n        return [endDate];\n    }\n    let date: any = resetDate(startDate, interval.interval_unit);\n    const formatStartDate = date.format(DATE_FORMAT);\n    const dates = [formatStartDate];\n    do {\n        date = dayjs(date).add(interval.interval_value, interval.interval_unit);\n        if (dayjs(date).isBefore(endDate)) {\n            dates.push(date.format(DATE_FORMAT));\n        }\n    } while (dayjs(date).isBefore(endDate));\n    return dates;\n}\n\nexport function getChartsData(tableDataCharts: any[], currentDate: [Dayjs, Dayjs]) {\n    const selectInterval: AutoInterval = getAutoInterval(currentDate);\n    const [startDate, endDate] = currentDate;\n    const intervalUnit: any = selectInterval.interval_unit || IntervalEnum.Auto;\n    const timeInterval: any = intervalUnit === IntervalEnum.Auto ? selectInterval : { interval_value: 1, interval_unit: intervalUnit };\n    const dates = getDateRange(startDate as Dayjs, endDate as Dayjs, timeInterval);\n    const tableDataMap = new Map();\n    const result: any[] = [];\n    const DATE_FORMAT_FROM_INTERVAL = formatDate(timeInterval.interval_unit);\n\n    tableDataCharts.forEach(e => {\n        const currentLocale = dayjs.locale();\n        const date = dayjs.utc(e['TT']).locale(currentLocale).format(DATE_FORMAT_FROM_INTERVAL);\n        tableDataMap.set(date, e['sum(cnt)']);\n    });\n    dates.forEach(date => {\n        const newDate = dayjs(date).format(DATE_FORMAT_FROM_INTERVAL);\n        if (!tableDataMap.get(newDate)) {\n            tableDataMap.set(newDate, null);\n        }\n    });\n\n    tableDataMap.forEach((value, key) => {\n        result.push({\n            TT: key,\n            ['sum(cnt)']: value,\n        });\n    });\n    return orderBy(result, ['TT'], ['asc']);\n}\n\nexport function convertColumnToRow(frame: any): Array<Record<string, any>> {\n    const fieldNames = frame.schema.fields.map((f: any) => f.name);\n    const columns = frame.data.values;\n\n    if (columns.length === 0) {\n        return [];\n    }\n\n    const numRows = columns[0].length;\n    const rows: Array<Record<string, any>> = [];\n\n    for (let i = 0; i < numRows; i++) {\n        const row: Record<string, any> = {};\n        for (let j = 0; j < columns.length; j++) {\n            row[fieldNames[j]] = columns[j][i];\n            if (isValidTimeFieldType(frame.schema.fields[j].type.toUpperCase())) {\n                // 如果是时间字段，转换为 Dayjs 对象\n                row[fieldNames[j]] = formatTimestampToDateTime(row[fieldNames[j]], frame.schema.fields[j].precision || 3);\n            }\n            if (frame.schema.fields[j].type === 'VARIANT') {\n                // 如果是 VARIANT 类型，转换为 JSON 对象\n                try {\n                    row[fieldNames[j]] = JSON.parse(row[fieldNames[j]]);\n                } catch (e) {\n                    console.error(`Error parsing VARIANT field ${fieldNames[j]}:`, e);\n                }\n            }\n        }\n        rows.push(row);\n    }\n\n    return rows;\n}\n\n// 通过查询 Doris 的字段判断类型，不依赖 Grafana 类型\nexport function convertColumnToRowViaFieldsType(frame: any, fields: any): Array<Record<string, any>> {\n    const fieldNames = frame.schema.fields.map((f: any) => f.name);\n    const columns = frame.data.values;\n\n    if (columns.length === 0) {\n        return [];\n    }\n\n    const numRows = columns[0].length;\n    const rows: Array<Record<string, any>> = [];\n\n    for (let i = 0; i < numRows; i++) {\n        const row: Record<string, any> = {};\n        for (let j = 0; j < columns.length; j++) {\n            row[fieldNames[j]] = columns[j][i];\n            if (isValidTimeFieldType(frame.schema.fields[j].type.toUpperCase())) {\n                // 如果是时间字段，转换为 Dayjs 对象\n                row[fieldNames[j]] = formatTimestampToDateTime(row[fieldNames[j]], frame.schema.fields[j].precision || 3);\n                // row[fieldNames[j]] = dayjs.utc(row[fieldNames[j]]).locale(currentLocale).format('YYYY-MM-DD HH:mm:ss.SSS');\n            }\n            const currentFieldInfo = fields.filter((item: any) => item.Field === frame.schema.fields[j].name)[0];\n            // 如果是 VARIANT 类型，转换为 JSON 对象\n            if (currentFieldInfo && currentFieldInfo.Type.toUpperCase() === 'VARIANT') {\n                try {\n                    row[fieldNames[j]] = JSON.parse(row[fieldNames[j]]);\n                } catch (e) {\n                    console.error(`Error parsing VARIANT field ${fieldNames[j]}:`, e);\n                }\n            }\n        }\n        rows.push(row);\n    }\n\n    return rows;\n}\n\n// 格式化时间戳为 DATETIME([number]) 格式\nexport function formatTimestampToDateTime(timestamp: any, precision = 3) {\n    const currentLocale = dayjs.locale();\n    // 基础格式：YYYY-MM-DD HH:mm:ss\n    let formatString = 'YYYY-MM-DD HH:mm:ss';\n\n    // 根据精度添加毫秒部分\n    if (precision > 0) {\n        formatString += `.${'S'.repeat(precision)}`;\n    }\n    // 转换时间戳并格式化\n    return dayjs.utc(timestamp).locale(currentLocale).format(formatString);\n}\n\nexport function formatTracesResData(frame: any) {\n    const { data } = frame;\n    const traceDataFrame: DataFrame = {\n        name: 'Trace ID',\n        refId: frame.schema?.refId || 'Trace ID',\n        fields: frame.schema?.fields.map((f: any, i: number) => ({\n            name: f.name,\n            type: f.type,\n            values: data.values[i],\n            typeInfo: f.typeInfo,\n            config: {},\n        })),\n        length: data.values[0].length,\n    };\n    try {\n        traceDataFrame.fields.forEach(f => {\n            if (f.name === 'serviceTags' || f.name === 'tags') {\n                f.type = FieldType.other;\n                f.values = f.values.map(item => JSON.parse(item));\n            }\n        });\n    } catch (err) {\n        console.log('err:', err);\n    }\n    console.log('traceDataFrame', traceDataFrame);\n    return traceDataFrame;\n}\n\nfunction getSearchTableData(tokenizeFields: any[], tableResult: any[]) {\n    const result: any = [...tokenizeFields];\n    tableResult.forEach(tableItem => {\n        result.forEach((token: any) => {\n            token['searchValue'] = tableItem[token.columnName];\n        });\n    });\n    return result;\n}\n\nfunction searchField(data: any[], searchString: string) {\n    return some(data, item => item.columnName === searchString);\n}\n\nfunction parseKeywords(keyword: string) {\n    if (keyword.length >= 2 && keyword[0] === keyword[keyword.length - 1] && (keyword[0] === `'` || keyword[0] === `\"`)) {\n        keyword = keyword.substring(1, keyword.length - 1);\n    }\n    return keyword;\n}\n\nfunction highlightDelimiter(inputStr: string, delimiter: string) {\n    const highlighted = inputStr.replace(new RegExp(`${delimiter}`, 'g'), `<mark>${delimiter}</mark>`);\n    return highlighted;\n}\n\nfunction insertUnderscore(arr: string[]) {\n    return arr.reduce((result: string[], item: string, index) => {\n        result.push(item);\n        if (index < arr.length - 1) {\n            result.push('_');\n        }\n        return result;\n    }, []);\n}\n\nfunction compare_ignore_quotes(s1: string, s2: string) {\n    // 移除双引号和单引号\n    const cleanS1 = s1.replace(/['\"]/g, '');\n    const cleanS2 = s2.replace(/['\"]/g, '');\n    // 比较\n    return cleanS1 === cleanS2;\n}\n\ntype SearchResultItem = { [key: string]: any };\nexport function generateHighlightedResults(data: { search_value: string; indexes: string[] }, result: SearchResultItem[]) {\n    const keyword: string = data.search_value || '';\n    const searchTableData = getSearchTableData(data.indexes, result);\n\n    // Detect simple Lucene \"field:value\" pattern so we can highlight the specified field\n    // even when `indexes` (tokenizeFields) is empty. Example: \"service_name:frontend\"\n    const luceneFieldMatch = keyword && keyword.match(/^\\s*([^\\s:]+)\\s*:/);\n    const luceneField = luceneFieldMatch ? luceneFieldMatch[1].replace(/['\"]+/g, '') : null;\n\n    const keywordsTokens: string[] = flatten(\n        Array.from(jsTokens(keyword))\n            .filter(item => item.type !== 'Punctuator')\n            .map(item => {\n                let res = item.value.toLowerCase();\n                return item.value.includes('_') ? item.value.split('_').map(str => str.toLowerCase()) : res;\n            }),\n    );\n\n    const _sourceResult = result.map(item => {\n        let itemSource = '';\n\n        for (const key in item) {\n            let highlightValue: any = item[key];\n            let itemValue: any = item[key];\n\n            if (typeof highlightValue === 'object') {\n                highlightValue = JSON.stringify(highlightValue);\n                itemValue = JSON.stringify(itemValue);\n            }\n\n            if (keyword && (searchField(searchTableData, key) || (luceneField && key === luceneField))) {\n                const strValue = typeof itemValue === 'string' ? itemValue : itemValue + '';\n\n                if (isWrappedInQuotes(keyword)) {\n                    const parsedKeyword = parseKeywords(keyword);\n                    if (parsedKeyword === strValue) {\n                        highlightValue = `<mark>${itemValue}</mark>`;\n                    } else if (strValue.includes(parsedKeyword)) {\n                        highlightValue = highlightDelimiter(strValue, parsedKeyword);\n                    }\n                } else {\n                    const tokenizedAns = Array.from(jsTokens(strValue)).map(item => item.value);\n                    let ans: string[] = [];\n\n                    if (tokenizedAns.includes(keyword)) {\n                        ans = tokenizedAns;\n                    } else {\n                        const ansWithUnderscore = flatten(\n                            tokenizedAns.map(item => {\n                                if (item.includes('_')) {\n                                    return insertUnderscore(item.split('_'));\n                                }\n                                return item;\n                            }),\n                        );\n                        ans = ansWithUnderscore;\n                    }\n\n                    if (ans.length > 0) {\n                        highlightValue = ans.reduce((acc: string, curr: string) => {\n                            if (\n                                keywordsTokens.filter(token => !isIgnorableHighlightToken(token)).find(token => compare_ignore_quotes(token, curr.toLowerCase())) ||\n                                compare_ignore_quotes(keyword.toLowerCase(), curr.toLowerCase())\n                            ) {\n                                return acc + `<mark>${curr}</mark>`;\n                            }\n                            return acc + curr;\n                        }, '');\n                    }\n                }\n            }\n\n            // ✅ 这里改成用 data-trace-id + class，方便事件委托识别\n            if (key === 'trace_id') {\n                const traceId = typeof itemValue === 'string' ? itemValue : String(itemValue);\n\n                const content = highlightValue || traceId;\n\n                highlightValue = `<a \n                href=\"javascript:void(0)\" \n                class=\"trace-link\" \n                data-trace-id=\"${traceId}\"\n            >${content}</a>`;\n            }\n\n            itemSource += `<span class=\"field-key\">${key}:</span>${highlightValue} `;\n        }\n\n        return {\n            _original: item,\n            _source: itemSource.trim(),\n        };\n    });\n\n    return _sourceResult;\n}\n\nexport const QUERY_TRACE_FIELDS = ['trace_id','span_id','parent_span_id','span_name','service_name']\n\n"],"names":["atom","atomWithStorage","selectAtom","atomWithL